package-performance:
  name: Package and performance (Node 24.x)
  runs-on: ubuntu-24.04
  # Nx 23 reads these self-hosted names. Require both repository secrets so
  # fork PRs, or partially configured environments, use only local caching.
  env:
    NX_SELF_HOSTED_REMOTE_CACHE_ACCESS_TOKEN: ${{ secrets.NX_REMOTE_CACHE_TOKEN != '' && secrets.NX_REMOTE_CACHE_SERVER != '' && secrets.NX_REMOTE_CACHE_TOKEN || '' }}
    NX_SELF_HOSTED_REMOTE_CACHE_SERVER: ${{ secrets.NX_REMOTE_CACHE_TOKEN != '' && secrets.NX_REMOTE_CACHE_SERVER != '' && secrets.NX_REMOTE_CACHE_SERVER || '' }}
  steps:

