const facadeModuleId = chunk.facadeModuleId?.replaceAll("\\", "/");
// The published package root is an embedding surface. Inject Sentry
// debug IDs into the executable entry and its lazy runtime module;
// shared chunks imported by the embedding entry must remain inert.
const executableFacades = ["src/cli.ts", "src/runtime.ts"];
const isExecutableFacade = executableFacades.some(
	(facade) =>
		facadeModuleId === facade || facadeModuleId?.endsWith(`/${facade}`),
);
if (!isExecutableFacade) return null;
return plugin.renderChunk?.(code, chunk, options, meta);

